// The gate of the Cemetery of Ashes in the west wall: the Ashen come through it into town, and it
// shuts behind them for good.
ü = cemetery_gate yaw=0 sentinels=false
// A cold grey light falling on it, so its stone shows against the dark beyond.
¿ = light y=4.5 color=0.5,0.52,0.62 radius=7
// The well down into the Abandoned Prison, in its sunken court.
W = exit map=abandoned_prison at=15,32,-90 label=Descend_the_well model=well
// The jungle trail east of the square: a hedged path winding under a canopy that closes in and
// darkens on the way to the cave mouth into the Verdant Hollow.
// (its lantern, hung from the timbers shoring the cave's mouth, lights the way in: ¢)
K = exit map=verdant_hollow at=25,33,180 label=Enter_the_cave model=cave_mouth yaw=180 on=c
u = torch radius=6 on=v
j = jungle_tree on=v
ö = mushrooms on=v
x = fungus radius=4 on=c
¢ = light y=2 color=1.0,0.72,0.4 radius=4 on=c
U = torch radius=5 on=w
õ = mushrooms on=w
F = fungus radius=4 on=y
z = mushrooms on=y
// Four grates down into the Harrow Sewers, tucked away in the town's corners, each over its own
// district below: in the north road's corner beside its gate, in the west lane below the cathedral
// terrace, at the harbour lane's west corner and on the quay. The sewers join up beneath, so each is
// a short way back to the others.
! = exit map=harrow_sewers at=35,2,90 label=Descend_into_the_sewers model=sewer_grate
? = exit map=harrow_sewers at=2,14,0 label=Descend_into_the_sewers model=sewer_grate
{ = exit map=harrow_sewers at=3,36,-90 label=Descend_into_the_sewers model=sewer_grate
} = exit map=harrow_sewers at=39,39,-90 label=Descend_into_the_sewers model=sewer_grate
// The Vesper Gate in the north wall, at the head of the cathedral steps: pale stone, standing open on
// Vesperholm. Nobody in town remembers it shut, or why it was opened. Lamps flank it and banners line
// the porch on the way up, so it reads from the foot of the steps.
( = exit map=vesperholm at=21,54,-90 label=Pass_the_Vesper_Gate model=vesper_gate yaw=90 on=;
// A cold light beside it, so its pale stone shows at the top of the porch.
) = light y=4.5 color=0.62,0.7,0.92 radius=7 on=;
// The north road, out through the wall to the Cinderhold.
N = exit map=cinderhold at=30,68,-90 label=Take_the_north_road model=road_gate yaw=-90 on=-
